def force_bytes(value):
    """
    Convert the input value to bytes. If the input value is a string, 
    it is encoded to bytes using UTF-8. If the input value is already 
    bytes, it is returned as is. Otherwise, a TypeError will be raised.

    :param value: Union[bytes, str]. The input value that needs to be converted to bytes.
    :return: bytes. The input value converted to bytes.
    """
    if isinstance(value, bytes):
        return value
    elif isinstance(value, str):
        return value.encode('utf-8')
    else:
        raise TypeError(f"Expected bytes or str, got {type(value).__name__}")

